    if (s == (int)a.size()) { ++cnt; return; }
    for (int i = s; i < (int)a.size(); ++i) {
        if (i > s && a[i] == a[i - 1]) continue;
        swap(a[s], a[i]);
        perm(a, s + 1, cnt);
        swap(a[s], a[i]);
    }
