bool exist(vector<string> board, string word) {
    int R = board.size(), C = R ? board[0].size() : 0;
    if ((long long)word.size() > (long long)R * C) return false;
    int need[128] = {0}, have[128] = {0};
    for (char ch : word) need[(unsigned char)ch]++;
    for (auto& row : board) for (char ch : row) have[(unsigned char)ch]++;
    for (int i = 0; i < 128; ++i) if (need[i] > have[i]) return false;
    // start from the rarer end: fewer start cells, earlier pruning
    if (have[(unsigned char)word.back()] < have[(unsigned char)word[0]])
        reverse(word.begin(), word.end());
    function<bool(int, int, int)> dfs = [&](int r, int c, int k) {
        if (r < 0 || c < 0 || r >= R || c >= C || board[r][c] != word[k]) return false;
        if (k + 1 == (int)word.size()) return true;
        char saved = board[r][c];
        board[r][c] = '#';                 // mark as used on this path
        bool ok = dfs(r + 1, c, k + 1) || dfs(r - 1, c, k + 1) ||
                  dfs(r, c + 1, k + 1) || dfs(r, c - 1, k + 1);
        board[r][c] = saved;               // unchoose
        return ok;
    };
    for (int r = 0; r < R; ++r)
        for (int c = 0; c < C; ++c)
            if (dfs(r, c, 0)) return true;
    return false;
}

struct TrieNode {
    TrieNode* next[26] = {};
    int cnt = 0;        // unfound words in this subtree
    string word;        // non-empty at the end of an unfound word
};

vector<string> findWords(vector<string> board, vector<string> words) {
    vector<unique_ptr<TrieNode>> pool;
    pool.push_back(make_unique<TrieNode>());
    TrieNode* root = pool[0].get();
    sort(words.begin(), words.end());
    words.erase(unique(words.begin(), words.end()), words.end());
    for (auto& w : words) {
        TrieNode* p = root;
        p->cnt++;
        for (char ch : w) {
            int i = ch - 'a';
            if (!p->next[i]) {
                pool.push_back(make_unique<TrieNode>());
                p->next[i] = pool.back().get();
            }
            p = p->next[i];
            p->cnt++;
        }
        p->word = w;
    }
    int R = board.size(), C = R ? board[0].size() : 0;
    vector<string> res;
    // returns how many words were found below, to update cnt on the path
    function<int(int, int, TrieNode*)> dfs = [&](int r, int c, TrieNode* parent) {
        if (r < 0 || c < 0 || r >= R || c >= C || board[r][c] == '#') return 0;
        TrieNode* p = parent->next[board[r][c] - 'a'];
        if (!p || p->cnt == 0) return 0;   // prune: nothing left here
        int found = 0;
        if (!p->word.empty()) { res.push_back(p->word); p->word.clear(); found = 1; }
        char saved = board[r][c];
        board[r][c] = '#';
        found += dfs(r + 1, c, p) + dfs(r - 1, c, p) + dfs(r, c + 1, p) + dfs(r, c - 1, p);
        board[r][c] = saved;
        p->cnt -= found;
        return found;
    };
    for (int r = 0; r < R && root->cnt > 0; ++r)
        for (int c = 0; c < C; ++c)
            root->cnt -= dfs(r, c, root);
    return res;
}

def letter_combinations(digits: str) -> list[str]:
    if not digits:
        return []
    keys = {"2": "abc", "3": "def", "4": "ghi", "5": "jkl",
            "6": "mno", "7": "pqrs", "8": "tuv", "9": "wxyz"}
    res, cur = [], []

    def bt(i: int) -> None:
        if i == len(digits):
            res.append("".join(cur))
            return
        for ch in keys[digits[i]]:
            cur.append(ch)      # choose
            bt(i + 1)           # explore
            cur.pop()           # unchoose

    bt(0)
    return res

def restore_ip_addresses(s: str) -> list[str]:
    res, parts = [], []

    def bt(i: int) -> None:
        left_parts = 4 - len(parts)
        left_chars = len(s) - i
        if left_chars < left_parts or left_chars > 3 * left_parts:
            return                          # prune: cannot fit
        if left_parts == 0:
            res.append(".".join(parts))     # here left_chars == 0
            return
        for L in (1, 2, 3):
            seg = s[i:i + L]
            if len(seg) < L:
                break
            if (L > 1 and seg[0] == "0") or int(seg) > 255:
                break                       # longer segments fail too
            parts.append(seg)
            bt(i + L)
            parts.pop()

    bt(0)
    return res

vector<string> generateParenthesis(int n) {
    vector<string> res;
    string cur;
    function<void(int, int)> bt = [&](int open, int close) {
        if ((int)cur.size() == 2 * n) { res.push_back(cur); return; }
        if (open < n) {             // may still open a new pair
            cur.push_back('(');
            bt(open + 1, close);
            cur.pop_back();
        }
        if (close < open) {         // only close what is open
            cur.push_back(')');
            bt(open, close + 1);
            cur.pop_back();
        }
    };
    bt(0, 0);
    return res;
}

vector<vector<string>> solveNQueens(int n) {
    vector<vector<string>> res;
    vector<string> board(n, string(n, '.'));
    vector<bool> col(n), d1(2 * n - 1), d2(2 * n - 1);
    function<void(int)> place = [&](int r) {
        if (r == n) { res.push_back(board); return; }
        for (int c = 0; c < n; ++c) {
            // r - c is constant on one diagonal kind, r + c on the other
            if (col[c] || d1[r - c + n - 1] || d2[r + c]) continue;
            col[c] = d1[r - c + n - 1] = d2[r + c] = true;
            board[r][c] = 'Q';
            place(r + 1);
            board[r][c] = '.';
            col[c] = d1[r - c + n - 1] = d2[r + c] = false;
        }
    };
    place(0);
    return res;
}

