vector<vector<int>> permute(vector<int> nums) {
    vector<vector<int>> res;
    int n = nums.size();
    // slots [0, k) are fixed; choose which element goes to slot k
    function<void(int)> bt = [&](int k) {
        if (k == n) { res.push_back(nums); return; }
        for (int i = k; i < n; ++i) {
            swap(nums[k], nums[i]);   // choose nums[i] for slot k
            bt(k + 1);
            swap(nums[k], nums[i]);   // unchoose: restore the array
        }
    };
    bt(0);
    return res;
}

vector<vector<int>> permuteUnique(vector<int> nums) {
    sort(nums.begin(), nums.end());
    int n = nums.size();
    vector<vector<int>> res;
    vector<int> cur;
    vector<bool> used(n, false);
    function<void()> bt = [&]() {
        if ((int)cur.size() == n) { res.push_back(cur); return; }
        for (int i = 0; i < n; ++i) {
            if (used[i]) continue;
            // equal values are taken left to right only
            if (i > 0 && nums[i] == nums[i - 1] && !used[i - 1]) continue;
            used[i] = true; cur.push_back(nums[i]);
            bt();
            cur.pop_back(); used[i] = false;
        }
    };
    bt();
    return res;
}

def subsets(nums: list[int]) -> list[list[int]]:
    res, cur = [], []

    def bt(start: int) -> None:
        res.append(cur[:])          # copy: cur keeps changing
        for i in range(start, len(nums)):
            cur.append(nums[i])
            bt(i + 1)               # only later indices: no reordering
            cur.pop()

    bt(0)
    return res

vector<vector<int>> subsetsWithDup(vector<int> nums) {
    sort(nums.begin(), nums.end());
    vector<vector<int>> res;
    vector<int> cur;
    function<void(int)> bt = [&](int start) {
        res.push_back(cur);                     // every node is a subset
        for (int i = start; i < (int)nums.size(); ++i) {
            if (i > start && nums[i] == nums[i - 1]) continue;  // same branch
            cur.push_back(nums[i]);
            bt(i + 1);
            cur.pop_back();
        }
    };
    bt(0);
    return res;
}

vector<vector<int>> combinationSum2(vector<int> cand, int target) {
    sort(cand.begin(), cand.end());
    vector<vector<int>> res;
    vector<int> cur;
    function<void(int, int)> bt = [&](int start, int rem) {
        if (rem == 0) { res.push_back(cur); return; }
        for (int i = start; i < (int)cand.size(); ++i) {
            if (cand[i] > rem) break;                          // sorted, positive
            if (i > start && cand[i] == cand[i - 1]) continue; // duplicate branch
            cur.push_back(cand[i]);
            bt(i + 1, rem - cand[i]);                          // each item once
            cur.pop_back();
        }
    };
    bt(0, target);
    return res;
}

def partition(s: str) -> list[list[str]]:
    n = len(s)
    # is_pal[i][j]: s[i..j] is a palindrome, filled from short to long
    is_pal = [[False] * n for _ in range(n)]
    for i in range(n - 1, -1, -1):
        for j in range(i, n):
            is_pal[i][j] = s[i] == s[j] and (j - i < 2 or is_pal[i + 1][j - 1])
    res, cur = [], []

    def bt(start: int) -> None:
        if start == n:
            res.append(cur[:])
            return
        for end in range(start, n):
            if is_pal[start][end]:
                cur.append(s[start:end + 1])
                bt(end + 1)
                cur.pop()

    bt(0)
    return res

void solveSudoku(vector<vector<char>>& b) {
    int row[9] = {}, col[9] = {}, box[9] = {};  // bit d = digit d+1 used
    vector<pair<int, int>> empty;
    for (int r = 0; r < 9; ++r)
        for (int c = 0; c < 9; ++c) {
            if (b[r][c] == '.') { empty.push_back({r, c}); continue; }
            int bit = 1 << (b[r][c] - '1');
            row[r] |= bit; col[c] |= bit; box[r / 3 * 3 + c / 3] |= bit;
        }
    auto freeMask = [&](int r, int c) {
        return ~(row[r] | col[c] | box[r / 3 * 3 + c / 3]) & 0x1FF;
    };
    function<bool(int)> solve = [&](int k) {
        if (k == (int)empty.size()) return true;
        int best = k, bestCnt = 10;        // MRV: fewest candidates first
        for (int i = k; i < (int)empty.size(); ++i) {
            int cnt = __builtin_popcount(freeMask(empty[i].first, empty[i].second));
            if (cnt < bestCnt) { bestCnt = cnt; best = i; }
        }
        swap(empty[k], empty[best]);
        auto [r, c] = empty[k];
        int bx = r / 3 * 3 + c / 3;
        for (int avail = freeMask(r, c); avail; avail &= avail - 1) {
            int bit = avail & -avail;
            row[r] |= bit; col[c] |= bit; box[bx] |= bit;
            b[r][c] = '1' + __builtin_ctz(bit);
            if (solve(k + 1)) return true;
            row[r] ^= bit; col[c] ^= bit; box[bx] ^= bit;
        }
        b[r][c] = '.';
        swap(empty[k], empty[best]);
        return false;
    };
    solve(0);
}

vector<string> addOperators(string num, int target) {
    vector<string> res;
    string expr;
    int n = num.size();
    // value: expression so far; last: last signed operand (undone by '*')
    function<void(int, long long, long long)> bt =
        [&](int i, long long value, long long last) {
        if (i == n) { if (value == target) res.push_back(expr); return; }
        size_t len = expr.size();
        long long operand = 0;
        for (int j = i; j < n; ++j) {
            if (j > i && num[i] == '0') break;       // no leading zeros
            operand = operand * 10 + (num[j] - '0');
            string s = num.substr(i, j - i + 1);
            if (i == 0) {
                expr += s; bt(j + 1, operand, operand); expr.resize(len);
                continue;
            }
            expr += "+" + s; bt(j + 1, value + operand, operand); expr.resize(len);
            expr += "-" + s; bt(j + 1, value - operand, -operand); expr.resize(len);
            expr += "*" + s;
            bt(j + 1, value - last + last * operand, last * operand);
            expr.resize(len);
        }
    };
    bt(0, 0, 0);
    return res;
}

vector<string> removeInvalidParentheses(string s) {
    int rmL = 0, rmR = 0;            // exact minimal removals of each kind
    for (char ch : s) {
        if (ch == '(') rmL++;
        else if (ch == ')') { if (rmL > 0) rmL--; else rmR++; }
    }
    vector<string> res;
    string cur;
    int n = s.size();
    // open: unmatched '(' in cur; l, r: removals still owed;
    // prevDel: was s[i-1] deleted (dedupe inside runs of equal chars)
    function<void(int, int, int, int, bool)> dfs =
        [&](int i, int open, int l, int r, bool prevDel) {
        if (l + r > n - i) return;               // not enough chars left
        if (i == n) { if (open == 0) res.push_back(cur); return; }
        char ch = s[i];
        // in a run like "))))" delete only a prefix of the run
        bool canDel = i == 0 || s[i - 1] != ch || prevDel;
        if (canDel && ch == '(' && l > 0) dfs(i + 1, open, l - 1, r, true);
        if (canDel && ch == ')' && r > 0) dfs(i + 1, open, l, r - 1, true);
        if (ch == ')' && open == 0) return;      // keeping it is invalid
        cur.push_back(ch);
        dfs(i + 1, open + (ch == '(') - (ch == ')'), l, r, false);
        cur.pop_back();
    };
    dfs(0, 0, rmL, rmR, false);
    return res;
}

// מספר המסלולים (open tours) של פרש שמבקרים בכל n*n המשבצות פעם אחת, החל מ-(r, c)
long long countTours(int n, int r, int c) {
    static const int dr[] = {2, 1, -1, -2, -2, -1, 1, 2};
    static const int dc[] = {1, 2, 2, 1, -1, -2, -2, -1};
    vector<vector<bool>> used(n, vector<bool>(n, false));
    auto dfs = [&](auto&& self, int x, int y, int visited) -> long long {
        if (visited == n * n) return 1;                // כל הלוח כוסה
        long long total = 0;
        for (int d = 0; d < 8; ++d) {
            int nx = x + dr[d], ny = y + dc[d];
            if (nx < 0 || ny < 0 || nx >= n || ny >= n || used[nx][ny]) continue;
            used[nx][ny] = true;                       // choose
            total += self(self, nx, ny, visited + 1);  // explore
            used[nx][ny] = false;                      // unchoose
        }
        return total;
    };
    used[r][c] = true;
    return dfs(dfs, r, c, 1);
}

vector<string> wordBreak(const string& s, const vector<string>& wordDict) {
    unordered_set<string> dict(wordDict.begin(), wordDict.end());
    size_t maxLen = 0;
    for (auto& w : wordDict) maxLen = max(maxLen, w.size());
    unordered_map<size_t, vector<string>> memo;        // start -> כל המשפטים של s[start..]
    auto solve = [&](auto&& self, size_t start) -> const vector<string>& {
        auto it = memo.find(start);
        if (it != memo.end()) return it->second;
        vector<string> res;
        if (start == s.size()) res.push_back("");      // משפט ריק: סוף מוצלח
        for (size_t len = 1; len <= maxLen && start + len <= s.size(); ++len) {
            string w = s.substr(start, len);
            if (!dict.count(w)) continue;
            for (const string& rest : self(self, start + len))
                res.push_back(rest.empty() ? w : w + " " + rest);
        }
        return memo[start] = move(res);
    };
